# kuccl 导出符号清单（version script / linker map）
#
# ╓ 机制 ─────────────────────────────────────────────────────────────╖
# 链接期强制：本文件是 .so 动态符号表的唯一事实来源——
#   · 列在 KUCCL_1.1 下的符号 → 导出
#   · 其余全部 local（即使源码漏写 KUCCL_API 也绝不意外导出）
#   · 与 build.sh 的 nm 门禁（12 符号）互为校验
# ╓ 防呆原理 ─────────────────────────────────────────────────────────╖
#   漏标 KUCCL_API（hidden）→ 符号不进动态表 → 链接后核对发现缺失 →
#   build.sh 门禁①失败（构建期拦截，不再是运行时 undefined symbol）
# ╓ 符号面（对齐评审约定）────────────────────────────────────────────╖
#   公开集合接口 4 个（AllGather/AllReduce/Broadcast/AllToAll）+
#   通信域管理 4 + Test 1 + 生产化设施 3 = 12 个公开接口。
# ╓ 版本节点（为 ABI 演进预留）───────────────────────────────────────╖
#   后续新增接口 → 新增 KUCCL_1.2 节点，老程序仍解析到 1.1 符号。

KUCCL_1.1 {
  global:
    # 通信域管理（4）
    kucclGetUniqueId;
    kucclCommInitRankConfig;
    kucclCommDestroy;
    kucclCommSplit;
    # 集合通信（4，公开面）
    kucclAllGather;
    kucclAllReduce;
    kucclBroadcast;
    kucclAllToAll;
    # 异步测试（1）
    kucclTest;
    # 生产化设施（3）
    kucclGetLastError;
    kucclCommAbort;
    kucclFlushComm;
  local:
    *;
};
